class _AnimalPainter extends CustomPainter{final int type;final List<Color> f;_AnimalPainter(this.type,this.f);@override void paint(Canvas c,Size s){final p=Paint()..style=PaintingStyle.fill;final o=Paint()..style=PaintingStyle.stroke..strokeWidth=5..color=Colors.black87;final x=s.width/2,y=s.height/2;if(type==0){p.color=f[0];c.drawOval(Rect.fromCenter(center:Offset(x,y+35),width:210,height:125),p);c.drawOval(Rect.fromCenter(center:Offset(x,y-50),width:135,height:110),p);p.color=f[1];final q=Path()..moveTo(x-55,y-90)..lineTo(x-40,y-150)..lineTo(x-5,y-105)..close();c.drawPath(q,p);c.drawOval(Rect.fromCenter(center:Offset(x,y+35),width:210,height:125),o);c.drawOval(Rect.fromCenter(center:Offset(x,y-50),width:135,height:110),o);c.drawPath(q,o);}else if(type==1){p.color=f[0];c.drawOval(Rect.fromCenter(center:Offset(x,y),width:250,height:130),p);c.drawOval(Rect.fromCenter(center:Offset(x+135,y-5),width:75,height:65),p);c.drawOval(Rect.fromCenter(center:Offset(x-120,y),width:70,height:45),p);c.drawOval(Rect.fromCenter(center:Offset(x,y),width:250,height:130),o);c.drawOval(Rect.fromCenter(center:Offset(x+135,y-5),width:75,height:65),o);c.drawOval(Rect.fromCenter(center:Offset(x-120,y),width:70,height:45),o);}else{p.color=f[0];c.drawOval(Rect.fromCenter(center:Offset(x,y),width:120,height:190),p);p.color=f[1];c.drawOval(Rect.fromCenter(center:Offset(x-70,y-45),width:90,height:120),p);p.color=f[2];c.drawOval(Rect.fromCenter(center:Offset(x+70,y-45),width:90,height:120),p);c.drawOval(Rect.fromCenter(center:Offset(x,y),width:120,height:190),o);c.drawOval(Rect.fromCenter(center:Offset(x-70,y-45),width:90,height:120),o);c.drawOval(Rect.fromCenter(center:Offset(x+70,y-45),width:90,height:120),o);}}@override bool shouldRepaint(covariant _AnimalPainter old)=>true;}
