class _LetterGameState extends State<_LetterGame>{final r=math.Random();int target=0,score=0;late List<String> options;@override void initState(){super.initState();newRound();WidgetsBinding.instance.addPostFrameCallback((_)=>speak());}void newRound(){final s={<String>{_letters[target]}};while(s.length<4)s.add(_letters[r.nextInt(_letters.length)]);options=s.toList()..shuffle(r);}void speak()=>VoiceService.arabic(_sounds[target]);void answer(String x){if(x!=_letters[target]){VoiceService.arabic('حاول مرة أخرى');return;}setState((){score++;target=r.nextInt(_letters.length);newRound();});WidgetsBinding.instance.addPostFrameCallback((_)=>speak());}@override Widget build(BuildContext c)=>_Page('لعبة الحروف',[const Text('استمع ثم اختر الحرف الصحيح',textAlign:TextAlign.center),Text(_letters[target],style:const TextStyle(fontSize:82,fontWeight:FontWeight.w900)),_Btn('🔊 نطق السؤال',const Color(0xFF18A7E8),speak),Text('النقاط: ${_ar(score)}'),for(final x in options)_Btn(x,const Color(0xFF7652FF),()=>answer(x))]);}
